import numpy as np

def _tokens(text):
    PUNCT = "!\"$%&'()*+,-./:;<=>?@[\\]^_`{|}~„“”‚‘’"
    stripped = "".join(ch for ch in text.lower() if ch not in PUNCT)
    return " ".join(stripped.split()).split()

def build_vectors(docs):
    doc_tokens = [_tokens(d) for d in docs]
    vocab = sorted({t for toks in doc_tokens for t in toks})
    pos = {t: i for i, t in enumerate(vocab)}
    n = len(docs)
    df = np.zeros(len(vocab))
    for toks in doc_tokens:
        for t in set(toks):
            df[pos[t]] += 1.0
    idf = np.log((n + 1.0) / (df + 1.0)) + 1.0
    m = np.zeros((n, len(vocab)))
    for i, toks in enumerate(doc_tokens):
        for t in toks:
            m[i, pos[t]] += 1.0
        nz = m[i] > 0
        m[i, nz] = (m[i, nz] / len(toks)) * idf[nz]
    return vocab, pos, m

def _query_vec(vocab, pos, m, query):
    n = m.shape[0]
    v = np.zeros(len(vocab))
    for t in _tokens(query):
        if t in pos:
            v[pos[t]] += 1.0
    total = v.sum()
    if total > 0:
        nz = v > 0
        df = (m[:, nz] > 0).sum(axis=0)
        v[nz] = (v[nz] / total) * (np.log((n + 1.0) / (df + 1.0)) + 1.0)
    return v

def rank(query, docs, k):
    vocab, pos, m = build_vectors(docs)
    v = _query_vec(vocab, pos, m, query)
    norms = np.linalg.norm(m, axis=1) * np.linalg.norm(v)
    norms[norms == 0.0] = 1.0
    scores = (m @ v) / norms
    order = sorted(range(len(docs)), key=lambda i: (-scores[i], i))
    return order[:k]

def recall_at_k(relevant, ranked, k):
    rel = set(relevant)
    if not rel:
        raise ValueError("relevant darf nicht leer sein")
    return len(set(ranked[:k]) & rel) / len(rel)

# rank("Wie lange läuft der Vertrag?", DOCS, 1) -> [2]

