import numpy as np

def _tokens(text):
    PUNCT = "!\"$%&'()*+,-./:;<=>?@[\\]^_`{|}~„“”‚‘’"
    stripped = "".join(ch for ch in text.lower() if ch not in PUNCT)
    return " ".join(stripped.split()).split()

def build_index(docs):
    doc_tokens = [_tokens(d) for d in docs]
    vocab = sorted({t for toks in doc_tokens for t in toks})
    pos = {t: i for i, t in enumerate(vocab)}
    n = len(docs)
    df = np.zeros(len(vocab))
    for toks in doc_tokens:
        for t in set(toks):
            df[pos[t]] += 1.0
    idf = np.log((n + 1.0) / (df + 1.0)) + 1.0
    m = np.zeros((n, len(vocab)))
    for i, toks in enumerate(doc_tokens):
        for t in toks:
            m[i, pos[t]] += 1.0
        nz = m[i] > 0
        m[i, nz] = (m[i, nz] / len(toks)) * idf[nz]
    return {"vocab": vocab, "pos": pos, "matrix": m}

def rank_query(index, query):
    m = index["matrix"]
    n = m.shape[0]
    v = np.zeros(m.shape[1])
    for t in _tokens(query):
        if t in index["pos"]:
            v[index["pos"][t]] += 1.0
    total = v.sum()
    if total > 0:
        nz = v > 0
        df = (m[:, nz] > 0).sum(axis=0)
        v[nz] = (v[nz] / total) * (np.log((n + 1.0) / (df + 1.0)) + 1.0)
    norms = np.linalg.norm(m, axis=1) * np.linalg.norm(v)
    norms[norms == 0.0] = 1.0
    scores = (m @ v) / norms
    return sorted(range(n), key=lambda i: (-scores[i], i))

def evaluate(index, queries, relevant_sets, k):
    recalls = []
    rrs = []
    for query, relevant in zip(queries, relevant_sets):
        rel = set(relevant)
        order = rank_query(index, query)
        recalls.append(len(set(order[:k]) & rel) / len(rel))
        rr = 0.0
        for position, doc in enumerate(order, start=1):
            if doc in rel:
                rr = 1.0 / position
                break
        rrs.append(rr)
    return {"recall_at_k": sum(recalls) / len(recalls), "mrr": sum(rrs) / len(rrs)}

# evaluate(build_index(B_DOCS), B_QUERIES, B_RELEVANT, 1) -> {'recall_at_k': 0.625, 'mrr': 0.875}

# evaluate(...) k=1 -> recall 0.625, mrr 0.875; k=3 -> recall 1.0

