def antwort(anfrage, docs):
    def terme(s):
        return {w for w in s.lower().split() if len(w) >= 4}
    q = terme(anfrage)
    punkte = [len(q & terme(d)) for d in docs]
    if max(punkte) == 0:
        return "kein treffer"
    best = punkte.index(max(punkte))
    saetze = docs[best].split(".")
    for satz in saetze:
        if q & terme(satz):
            return satz.strip()
    return saetze[0].strip()

