REQUIRED_FIELDS = ["frage", "methode", "datensatz", "ergebnis", "limitation"]

def review_paper_card(card):
    """Structural review: missing text fields and claims without supporting numbers."""
    if not isinstance(card, dict):
        raise ValueError("card muss ein dict sein")
    missing = [f for f in REQUIRED_FIELDS if not isinstance(card.get(f), str) or not card.get(f).strip()]
    unsupported = []
    claims = card.get("claims", [])
    if not isinstance(claims, list):
        raise ValueError("claims muss eine Liste sein")
    for index, claim in enumerate(claims):
        evidence = claim.get("evidence") if isinstance(claim, dict) else None
        ok = False
        if isinstance(evidence, dict):
            baseline, system = evidence.get("baseline"), evidence.get("system")
            if isinstance(baseline, (int, float)) and isinstance(system, (int, float)):
                if not isinstance(baseline, bool) and not isinstance(system, bool):
                    ok = system > baseline
        if not ok:
            unsupported.append(index)
    return {"missing_fields": missing, "unsupported_claims": unsupported}

